[sop_c_06] C - SOP: Langkah 4: Pembuatan Kode Pengujian Fitur Modern C (Generic Selection & Safe Pointer)
Dokumen: Standar Operasional Prosedur (SOP): Setup dan Konfigurasi Lingkungan Pemrograman C (C17 / C23 Standards & Make/CMake)
Kategori: SOP Setup & Environment
Sumber: knowledge-base/sop-setup-environment-c.md

Buat berkas `src/main.c`:
```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

// Uji fitur C11/C17/C23 Generic Selection (_Generic)
#define type_name(x) _Generic((x), \
    int: "int", \
    float: "float", \
    double: "double", \
    char*: "string", \
    default: "unknown")

typedef struct {
    int id;
    const char* name;
    bool active;
} SystemConfig;

int main(void) {
    // Alokasi memori dinamis aman
    SystemConfig* cfg = (SystemConfig*)malloc(sizeof(SystemConfig));
    if (cfg == NULL) {
        fprintf(stderr, "Galat: Gagal mengalokasikan memori!\n");
        return 1;
    }

    // Designated Initializers
    *cfg = (SystemConfig){ .id = 101, .name = "CintaMamaAI Kernel", .active = true };

    int num = 42;
    printf("Tipe data variabel num terdeteksi: %s\n", type_name(num));
    printf("Status Modul [%s]: %s\n", cfg->name, cfg->active ? "AKTIF" : "NONAKTIF");
    printf("Status: Lingkungan Bahasa C (C17/C23) berhasil diverifikasi dan aman.\n");

    // Pelepasan memori wajib guna mencegah memory leak
    free(cfg);
    cfg = NULL;

    return 0;
}
```

[sop_cpp_06] C++ - SOP: Langkah 4: Pengujian Fitur Modern C++20 (Concepts & Smart Pointers)
Dokumen: Standar Operasional Prosedur (SOP): Setup dan Konfigurasi Lingkungan Pemrograman C++ (Modern C++20 / C++23 & CMake)
Kategori: SOP Setup & Environment
Sumber: knowledge-base/sop-setup-environment-cpp.md

1. Buat direktori `src/` dan file `src/main.cpp`:
   ```bash
   mkdir src
   ```
2. Tulis kode pengujian pada `src/main.cpp`:
   ```cpp
   #include <iostream>
   #include <memory>
   #include <concepts>
   #include <string>

   // Uji fitur C++20 Concepts
   template <typename T>
   concept Printable = requires(T a) {
       std::cout << a;
   };

   template <Printable T>
   void print_message(const T& msg) {
       std::cout << msg << std::endl;
   }

   int main() {
       // Uji Modern Smart Pointer
       auto ptr = std::make_unique<std::string>("Status: Lingkungan C++20 berhasil diverifikasi dan siap dipakai.");
       print_message(*ptr);
       return 0;
   }
   ```

