This code consumes a ReadableStream via a ReadableStreamDefaultReader. The reader does not implement the disposable
protocol, so we use `adopt()` to register it to the stack.
{
  using disposer = new DisposableStack();
  const reader = disposer.adopt(stream.getReader(), (reader) =>
    reader.releaseLock(),
  );
  const { value, done } = reader.read();
  if (!done) {
    // Process the value
  }
