/**
 * @param {SomeType} myValue
 */
function doSomething(myValue) {
    // ...
}
// -----------------------------------------
import * as someModule from "./some-module";
/**
 * @param {someModule.SomeType} myValue
 */
function doSomething(myValue) {
    // ...
}
// -----------------------------------------
/**
 * @param {import("./some-module").SomeType} myValue
 */
function doSomething(myValue) {
    // ...
}

